#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package MQTTnet@4.1.5 #:package WolverineFx@1.10.0 #:package WolverineFx.MQTT@1.10.0 #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable  using System.Text.Json; using Wolverine; using Wolverine.MQTT; using MQTTnet; using MQTTnet.Client; using MQTTnet.Protocol;  // 1. 定义跨进程消息包装器 public record ProcessMessage<T>(T Message) : IMessage     where T : IMessage;  // 2. Wolverine消息处理器 public static class MqttMessageHandlers {     public static async Task Handle(ProcessMessage<IMessage> message, IMessageBus bus)     {         await bus.SendAsync(message.Message);     } }  // 3. 分布式事务中间件 public static class DistributedTransactionMiddleware {     public static async Task BeforeAsync(         IMessage message,          ITransactionCoordinator coordinator,         Envelope envelope)     {         var transaction = await coordinator.BeginTransactionAsync();         envelope.RegisterTransaction(transaction);     }      public static async Task AfterAsync(         IMessage message,         ITransactionCoordinator coordinator,         Envelope envelope)     {         var transaction = envelope.GetTransaction<ITransaction>();         await transaction.CommitAsync();     }      public static async Task OnErrorAsync(         IMessage message,         Exception ex,         ITransactionCoordinator coordinator,         Envelope envelope)     {         var transaction = envelope.GetTransaction<ITransaction>();         await transaction.RollbackAsync();     } }  // 4. DI扩展方法 public static class ServiceCollectionExtensions {     public static WolverineOptions UseMqttTransport(         this WolverineOptions options,         Action<MqttOptions> configureOptions)     {         // 配置MQTT         options.Services.Configure(configureOptions);                  // 配置Wolverine使用MQTT传输         options.UseMqttTransport(cfg =>         {             var options = cfg.Services.GetRequiredService<IOptions<MqttOptions>>().Value;                          cfg.AutoProvision = true;             cfg.AutoPurgeOnStartup = false;                          cfg.ConfigureOptions(opts =>             {                 opts.WithTcpServer(options.Server)                     .WithClientId(options.ClientId);             });                          cfg.ConfigurePublishing(pub =>             {                 pub.TopicName = options.Topic;                 pub.QualityOfServiceLevel = MqttQualityOfServiceLevel.AtLeastOnce;                 pub.Retain = true;             });         });                  // 添加分布式事务中间件         options.Policies.AddMiddleware<DistributedTransactionMiddleware>();                  return options;     } }  // 5. 配置选项 public class MqttOptions {     public string Server { get; set; } = "localhost";     public int Port { get; set; } = 1883;     public string ClientId { get; set; } = Guid.NewGuid().ToString();     public string Topic { get; set; } = "wolverine/messages"; }  // 6. 使用示例 builder.Host.UseWolverine(opts => {     opts.UseMqttTransport(c => c.Server = "localhost"); });
